local MillstoneQuillMaker = {}
local PRODUCTS = {
    iron_millstonequill = { name = "Železni vreteno mlinskih kamnov", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni vreteno mlinskih kamnov za mlinarje." },
    bronze_millstonequill = { name = "Bronast vreteno mlinskih kamnov", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast vreteno mlinskih kamnov za mlinarje." },
    silver_millstonequill = { name = "Srebrn vreteno mlinskih kamnov", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn vreteno mlinskih kamnov za mlinarje." },
    gilded_millstonequill = { name = "Pozlačen vreteno mlinskih kamnov", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen vreteno mlinskih kamnov za mlinarje." },
    jewel_set_millstonequill = { name = "Draguljast vreteno mlinskih kamnov", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast vreteno mlinskih kamnov za mlinarje." },
    royal_sovereign_millstonequill = { name = "Kraljevski suveren vreteno mlinskih kamnov", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren vreteno mlinskih kamnov z biseri za krono." },
}
local BUILDINGS = {
    millstonequill_workshop = { name = "Millstonequill delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    millstonequill_house = { name = "Millstonequill hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_millstonequill_atelier = { name = "Mojstrski millstonequill atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_millstonequill_palace = { name = "Suverena millstonequill palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
MillstoneQuillMaker.ironStock=18; MillstoneQuillMaker.bronzeStock=14; MillstoneQuillMaker.woodStock=10; MillstoneQuillMaker.leatherStock=8; MillstoneQuillMaker.silverStock=8; MillstoneQuillMaker.goldStock=6; MillstoneQuillMaker.jewelStock=4; MillstoneQuillMaker.pearlStock=4
MillstoneQuillMaker.productStock = {}; MillstoneQuillMaker.buildings = {}; MillstoneQuillMaker.maker = nil; MillstoneQuillMaker.activeMaking = {}; MillstoneQuillMaker.totalProducts = 0; MillstoneQuillMaker.dayTimer = 0
function MillstoneQuillMaker.init() MillstoneQuillMaker.ironStock=18; MillstoneQuillMaker.bronzeStock=14; MillstoneQuillMaker.woodStock=10; MillstoneQuillMaker.leatherStock=8; MillstoneQuillMaker.silverStock=8; MillstoneQuillMaker.goldStock=6; MillstoneQuillMaker.jewelStock=4; MillstoneQuillMaker.pearlStock=4; MillstoneQuillMaker.productStock={}; MillstoneQuillMaker.buildings={}; MillstoneQuillMaker.maker=nil; MillstoneQuillMaker.activeMaking={}; MillstoneQuillMaker.totalProducts=0; MillstoneQuillMaker.dayTimer=0; print("[MillstoneQuillMaker] Royal Millstone Quill Maker System initialized (6 products, 4 buildings)") end
function MillstoneQuillMaker.hireMaker(n,s) s=s or math.random(55,90); local c=585+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; MillstoneQuillMaker.maker={name=n or ("Vretenar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Vretenar najet: %s (spretnost: %d)",MillstoneQuillMaker.maker.name,s),"success") end; return true end
function MillstoneQuillMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function MillstoneQuillMaker.build(id) local ok,e=MillstoneQuillMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(MillstoneQuillMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function MillstoneQuillMaker.getQualityBonus() local b=0; for _,bd in ipairs(MillstoneQuillMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function MillstoneQuillMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and MillstoneQuillMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and MillstoneQuillMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and MillstoneQuillMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and MillstoneQuillMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and MillstoneQuillMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and MillstoneQuillMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and MillstoneQuillMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and MillstoneQuillMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #MillstoneQuillMaker.buildings==0 then return false,"Potrebna vretena delavnica" end; if not MillstoneQuillMaker.maker then return false,"Potreben vretenar" end; return true end
function MillstoneQuillMaker.make(pt,qty) qty=qty or 1; local ok,e=MillstoneQuillMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then MillstoneQuillMaker.ironStock=MillstoneQuillMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then MillstoneQuillMaker.bronzeStock=MillstoneQuillMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then MillstoneQuillMaker.woodStock=MillstoneQuillMaker.woodStock-d.woodCost*qty end; if d.leatherCost then MillstoneQuillMaker.leatherStock=MillstoneQuillMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then MillstoneQuillMaker.silverStock=MillstoneQuillMaker.silverStock-d.silverCost*qty end; if d.goldCost then MillstoneQuillMaker.goldStock=MillstoneQuillMaker.goldStock-d.goldCost*qty end; if d.jewelCost then MillstoneQuillMaker.jewelStock=MillstoneQuillMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then MillstoneQuillMaker.pearlStock=MillstoneQuillMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if MillstoneQuillMaker.maker then t=math.max(1,t-math.floor(MillstoneQuillMaker.maker.skill/13)) end; table.insert(MillstoneQuillMaker.activeMaking,{id="millstonequill_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function MillstoneQuillMaker.completeMaking(m) local q=1.0+(MillstoneQuillMaker.getQualityBonus()/100); if MillstoneQuillMaker.maker then q=q+(MillstoneQuillMaker.maker.skill/140) end; q=math.min(2.5,q); MillstoneQuillMaker.productStock[m.productType]=(MillstoneQuillMaker.productStock[m.productType] or 0)+m.quantity; MillstoneQuillMaker.totalProducts=MillstoneQuillMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if MillstoneQuillMaker.maker then MillstoneQuillMaker.maker.itemsMade=MillstoneQuillMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then MillstoneQuillMaker.maker.skill=math.min(100,MillstoneQuillMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Vreteno izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"millstonequill.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function MillstoneQuillMaker.update(dt) if not _G.state then return end; MillstoneQuillMaker.dayTimer=MillstoneQuillMaker.dayTimer+dt; if MillstoneQuillMaker.dayTimer>=30 then MillstoneQuillMaker.dayTimer=0; for i=#MillstoneQuillMaker.activeMaking,1,-1 do local m=MillstoneQuillMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then MillstoneQuillMaker.completeMaking(m); table.remove(MillstoneQuillMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(MillstoneQuillMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if MillstoneQuillMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function MillstoneQuillMaker.getStats() return {ironStock=MillstoneQuillMaker.ironStock,bronzeStock=MillstoneQuillMaker.bronzeStock,woodStock=MillstoneQuillMaker.woodStock,leatherStock=MillstoneQuillMaker.leatherStock,silverStock=MillstoneQuillMaker.silverStock,goldStock=MillstoneQuillMaker.goldStock,jewelStock=MillstoneQuillMaker.jewelStock,pearlStock=MillstoneQuillMaker.pearlStock,productStock=MillstoneQuillMaker.productStock,numBuildings=#MillstoneQuillMaker.buildings,hasMaker=MillstoneQuillMaker.maker~=nil,makerName=MillstoneQuillMaker.maker and MillstoneQuillMaker.maker.name or "—",makerSkill=MillstoneQuillMaker.maker and MillstoneQuillMaker.maker.skill or 0,activeMaking=#MillstoneQuillMaker.activeMaking,totalProducts=MillstoneQuillMaker.totalProducts} end
return MillstoneQuillMaker
